package com.crossborder.erp.warehouse.repair;

import org.springframework.web.bind.annotation.*;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.data.redis.core.StringRedisTemplate;
import jakarta.servlet.http.HttpServletRequest;
import java.util.*;
import static com.crossborder.erp.warehouse.repair.RepairSupport.*;

@RestController
public class UserRepairController {
 private final RepairSupport s;private final StringRedisTemplate redis;private final BCryptPasswordEncoder encoder=new BCryptPasswordEncoder();
 private final String fields="id,username,real_name AS realName,email,phone,avatar,status,last_login_time AS lastLoginTime,create_time AS createTime,update_time AS updateTime";
 public UserRepairController(RepairSupport s,StringRedisTemplate redis){this.s=s;this.redis=redis;}
 private String password(Map<String,Object>b,String k){String p=str(b.get(k));if(p.length()<12||p.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>72)throw bad("密码至少12位，UTF-8不超过72字节");return encoder.encode(p);}
 @GetMapping("/user/list") public Object users(@RequestParam Map<String,String>p){List<Object>a=new ArrayList<>();String w=" WHERE deleted=0"+s.eq("status","status",p,a);if(!str(p.get("keyword")).isEmpty()){w+=" AND (username LIKE ? OR real_name LIKE ? OR email LIKE ?)";for(int i=0;i<3;i++)a.add("%"+p.get("keyword")+"%");}if(!str(p.get("roleId")).isEmpty()){w+=" AND EXISTS(SELECT 1 FROM erp_user.t_user_role ur WHERE ur.user_id=t_user.id AND ur.role_id=?)";a.add(p.get("roleId"));}if(!str(p.get("departmentId")).isEmpty()){w+=" AND EXISTS(SELECT 1 FROM erp_user.t_user_department ud WHERE ud.user_id=t_user.id AND ud.department_id=?)";a.add(p.get("departmentId"));}return s.page("SELECT "+fields+" FROM erp_user.t_user",w,a,p," ORDER BY create_time DESC,id DESC");}
 @GetMapping("/user/{id}") public Object user(@PathVariable long id){Map<String,Object>u=s.one("SELECT "+fields+" FROM erp_user.t_user WHERE id=? AND deleted=0",id);u.put("roles",s.rows("SELECT r.id,r.role_code AS roleCode,r.role_name AS roleName FROM erp_user.t_role r JOIN erp_user.t_user_role ur ON ur.role_id=r.id WHERE ur.user_id=?",id));u.put("departments",s.rows("SELECT d.id,d.dept_name AS deptName FROM erp_user.t_department d JOIN erp_user.t_user_department ud ON ud.department_id=d.id WHERE ud.user_id=?",id));return u;}
 @PostMapping("/user") public Object create(@RequestBody Map<String,Object>b){s.required(b,"username","password");long id=s.id();s.db.update("INSERT INTO erp_user.t_user(id,username,password,real_name,email,phone,status) VALUES(?,?,?,?,?,?,1)",id,str(b.get("username")),password(b,"password"),b.get("realName"),blankNull(b.get("email")),b.get("phone"));return user(id);}
 private Object blankNull(Object x){return str(x).isBlank()?null:x;}
 private boolean admin(long id){return s.count("SELECT COUNT(*) FROM erp_user.t_user_role ur JOIN erp_user.t_role r ON r.id=ur.role_id WHERE ur.user_id=? AND LOWER(r.role_code) IN ('admin','super_admin') AND r.status=1",id)>0;}
 private void lockAdmins(){s.rows("SELECT id FROM erp_user.t_role WHERE LOWER(role_code) IN ('admin','super_admin') ORDER BY id FOR UPDATE");}
 private void protectLast(long id){if(admin(id)&&s.count("SELECT COUNT(DISTINCT u.id) FROM erp_user.t_user u JOIN erp_user.t_user_role ur ON ur.user_id=u.id JOIN erp_user.t_role r ON ur.role_id=r.id WHERE u.status=1 AND u.deleted=0 AND r.status=1 AND LOWER(r.role_code) IN ('admin','super_admin')")<=1)throw bad("不能移除最后一个有效管理员");}
 @PutMapping("/user") public Object update(@RequestBody Map<String,Object>b){long id=number(b.get("id"));return s.atomic(()->{lockAdmins();Map<String,Object>old=s.one("SELECT "+fields+" FROM erp_user.t_user WHERE id=? AND deleted=0 FOR UPDATE",id);int status=b.containsKey("status")?(int)number(b.get("status")):((Number)old.get("status")).intValue();if(status!=0&&status!=1)throw bad("Invalid status");if(status==0)protectLast(id);s.db.update("UPDATE erp_user.t_user SET real_name=?,email=?,phone=?,avatar=?,status=? WHERE id=?",b.getOrDefault("realName",old.get("realName")),blankNull(b.getOrDefault("email",old.get("email"))),b.getOrDefault("phone",old.get("phone")),b.getOrDefault("avatar",old.get("avatar")),status,id);if(status==0)redis.delete("token:"+id);return user(id);});}
 @PutMapping("/user/{id}/status") public Object status(@PathVariable long id,@RequestBody Map<String,Object>b){b.put("id",id);return update(b);}
 @DeleteMapping("/user/{id}") public Object delete(@PathVariable long id,HttpServletRequest req){if(id==(Long)req.getAttribute("repairUserId"))throw bad("不能删除当前登录账号");return s.atomic(()->{lockAdmins();protectLast(id);s.changed(s.db.update("UPDATE erp_user.t_user SET deleted=1,status=0 WHERE id=? AND deleted=0",id));redis.delete("token:"+id);return map("success",true);});}
 @PostMapping("/user/{id}/reset-password") public Object reset(@PathVariable long id,@RequestBody Map<String,Object>b){String hash=password(b,"newPassword");s.changed(s.db.update("UPDATE erp_user.t_user SET password=? WHERE id=? AND deleted=0",hash,id));redis.delete("token:"+id);return map("success",true);}
 @PostMapping("/user/change-password") public Object change(@RequestBody Map<String,Object>b,HttpServletRequest req){long id=(Long)req.getAttribute("repairUserId");String hash=password(b,"newPassword");return s.atomic(()->{String old=str(s.one("SELECT password FROM erp_user.t_user WHERE id=? FOR UPDATE",id).get("password"));if(!encoder.matches(str(b.get("oldPassword")),old))throw bad("原密码不正确");s.db.update("UPDATE erp_user.t_user SET password=? WHERE id=?",hash,id);redis.delete("token:"+id);return map("success",true);});}
 @PostMapping("/user/{id}/roles") public Object assign(@PathVariable long id,@RequestBody Map<String,Object>b){return s.atomic(()->{lockAdmins();s.one("SELECT id FROM erp_user.t_user WHERE id=? AND deleted=0 FOR UPDATE",id);Object raw=b.get("roleIds");if(!(raw instanceof List<?>))throw bad("roleIds must be array");List<Long>ids=((List<?>)raw).stream().map(RepairSupport::number).distinct().toList();boolean willAdmin=false;for(long role:ids){Map<String,Object>r=s.one("SELECT role_code,status FROM erp_user.t_role WHERE id=?",role);if(((Number)r.get("status")).intValue()==1&&Set.of("admin","super_admin").contains(str(r.get("role_code")).toLowerCase()))willAdmin=true;}if(!willAdmin)protectLast(id);s.db.update("DELETE FROM erp_user.t_user_role WHERE user_id=?",id);for(long role:ids)s.db.update("INSERT INTO erp_user.t_user_role(id,user_id,role_id) VALUES(?,?,?)",s.id(),id,role);redis.delete("token:"+id);return user(id);});}
 private final String roleSelect="SELECT id,role_code AS roleCode,role_name AS roleName,description,status,sort,create_time AS createTime FROM erp_user.t_role";
 @GetMapping("/role/list") public Object roles(@RequestParam Map<String,String>p){List<Object>a=new ArrayList<>();String w=" WHERE 1=1"+s.eq("status","status",p,a)+s.like("role_name","keyword",p,a);return p.containsKey("current")?s.page(roleSelect,w,a,p," ORDER BY sort,id"):s.rows(roleSelect+w+" ORDER BY sort,id",a.toArray());}
 @GetMapping("/role/{id}") public Object role(@PathVariable long id){Map<String,Object>r=s.one(roleSelect+" WHERE id=?",id);r.put("permissions",s.rows("SELECT p.id,p.permission_code AS permissionCode,p.permission_name AS permissionName FROM erp_user.t_permission p JOIN erp_user.t_role_permission rp ON rp.permission_id=p.id WHERE rp.role_id=?",id));return r;}
 @PostMapping("/role") public Object addRole(@RequestBody Map<String,Object>b){s.required(b,"roleCode","roleName");String code=str(b.get("roleCode")).toLowerCase();if(Set.of("admin","super_admin").contains(code))throw bad("管理员角色由初始化流程维护");long id=s.id();s.db.update("INSERT INTO erp_user.t_role(id,role_code,role_name,description,status,sort) VALUES(?,?,?,?,1,?)",id,code,b.get("roleName"),b.get("description"),b.getOrDefault("sort",0));return role(id);}
 private void editableRole(long id){String code=str(s.one("SELECT role_code FROM erp_user.t_role WHERE id=?",id).get("role_code"));if(Set.of("admin","super_admin").contains(code.toLowerCase()))throw bad("不能修改内置管理员角色");}
 @PutMapping("/role") public Object editRole(@RequestBody Map<String,Object>b){long id=number(b.get("id"));editableRole(id);s.required(b,"roleName");s.changed(s.db.update("UPDATE erp_user.t_role SET role_name=?,description=?,status=?,sort=? WHERE id=?",b.get("roleName"),b.get("description"),b.getOrDefault("status",1),b.getOrDefault("sort",0),id));return role(id);}
 @DeleteMapping("/role/{id}") public Object removeRole(@PathVariable long id){return s.atomic(()->{lockAdmins();editableRole(id);if(s.count("SELECT COUNT(*) FROM erp_user.t_user_role WHERE role_id=?",id)>0)throw bad("角色已分配，不能删除");s.db.update("DELETE FROM erp_user.t_role_permission WHERE role_id=?",id);s.changed(s.db.update("DELETE FROM erp_user.t_role WHERE id=?",id));return map("success",true);});}
 @PostMapping("/role/{id}/permissions") public Object permissionAssign(@PathVariable long id,@RequestBody Map<String,Object>b){return s.atomic(()->{editableRole(id);if(!(b.get("permissionIds") instanceof List<?> ids))throw bad("permissionIds must be array");s.db.update("DELETE FROM erp_user.t_role_permission WHERE role_id=?",id);for(Object p:ids.stream().distinct().toList()){long pid=number(p);s.one("SELECT id FROM erp_user.t_permission WHERE id=?",pid);s.db.update("INSERT INTO erp_user.t_role_permission(id,role_id,permission_id) VALUES(?,?,?)",s.id(),id,pid);}return map("success",true);});}
 public static List<Map<String,Object>> tree(List<Map<String,Object>> rows){Map<Long,Map<String,Object>> idx=new LinkedHashMap<>();for(Map<String,Object>r:rows){r.put("children",new ArrayList<Map<String,Object>>());idx.put(number(r.get("id")),r);}List<Map<String,Object>>root=new ArrayList<>();for(Map<String,Object>r:rows){long parent=r.get("parentId")==null?0:number(r.get("parentId"));if(idx.containsKey(parent))((List<Map<String,Object>>)idx.get(parent).get("children")).add(r);else root.add(r);}return root;}
 @GetMapping("/permission/tree") public Object permissions(){return tree(s.rows("SELECT id,parent_id AS parentId,permission_code AS permissionCode,permission_name AS permissionName,permission_type AS permissionType,url AS path,icon,sort_order AS sort FROM erp_user.t_permission WHERE status=1 ORDER BY sort_order,id"));}
 private final String deptSelect="SELECT id,dept_name AS deptName,dept_code AS deptCode,parent_id AS parentId,leader,phone,email,sort,status,create_time AS createTime FROM erp_user.t_department";
 @GetMapping("/department/tree") public Object depts(){return tree(s.rows(deptSelect+" ORDER BY sort,id"));}
 @GetMapping("/department/list") public Object deptList(@RequestParam Map<String,String>p){List<Object>a=new ArrayList<>();return s.rows(deptSelect+" WHERE 1=1"+s.eq("parent_id","parentId",p,a)+" ORDER BY sort,id",a.toArray());}
 @PostMapping("/department") public Object addDept(@RequestBody Map<String,Object>b){s.required(b,"deptName","deptCode");long id=s.id();long parent=b.get("parentId")==null?0:number(b.get("parentId"));if(parent!=0)s.one(deptSelect+" WHERE id=?",parent);s.db.update("INSERT INTO erp_user.t_department(id,dept_name,dept_code,parent_id,leader,phone,email,sort,status) VALUES(?,?,?,?,?,?,?,?,?)",id,b.get("deptName"),b.get("deptCode"),parent,b.get("leader"),b.get("phone"),b.get("email"),b.getOrDefault("sort",0),b.getOrDefault("status",1));return s.one(deptSelect+" WHERE id=?",id);}
 @PutMapping("/department") public Object editDept(@RequestBody Map<String,Object>b){s.required(b,"id","deptName","deptCode");long id=number(b.get("id")),parent=b.get("parentId")==null?0:number(b.get("parentId"));return s.atomic(()->{s.rows("SELECT id FROM erp_user.t_department ORDER BY id FOR UPDATE");long cursor=parent;Set<Long>seen=new HashSet<>();while(cursor!=0){if(cursor==id||!seen.add(cursor))throw bad("部门层级不能循环");cursor=number(s.one("SELECT parent_id FROM erp_user.t_department WHERE id=?",cursor).get("parent_id"));}s.changed(s.db.update("UPDATE erp_user.t_department SET dept_name=?,dept_code=?,parent_id=?,leader=?,phone=?,email=?,sort=?,status=? WHERE id=?",b.get("deptName"),b.get("deptCode"),parent,b.get("leader"),b.get("phone"),b.get("email"),b.getOrDefault("sort",0),b.getOrDefault("status",1),id));return s.one(deptSelect+" WHERE id=?",id);});}
 @DeleteMapping("/department/{id}") public Object delDept(@PathVariable long id){return s.atomic(()->{s.rows("SELECT id FROM erp_user.t_department ORDER BY id FOR UPDATE");if(s.count("SELECT COUNT(*) FROM erp_user.t_department WHERE parent_id=?",id)>0||s.count("SELECT COUNT(*) FROM erp_user.t_user_department WHERE department_id=?",id)>0)throw bad("部门仍有子部门或成员");s.changed(s.db.update("DELETE FROM erp_user.t_department WHERE id=?",id));return map("success",true);});}
}
